import{z as A,x as d,o as t,c as p,q as r,j as o,D as n,d as E,s as l,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"值函数迭代","description":"","frontmatter":{"title":"值函数迭代","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/value-function-iteration.md","filePath":"econ/value-function-iteration.md","lastUpdated":1791063341000}'),B={name:"econ/value-function-iteration.md"};function v(_,a,c,m,u,T){const i=d("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="值函数迭代" tabindex="-1">值函数迭代 <a class="header-anchor" href="#值函数迭代" aria-label="Permalink to &quot;值函数迭代&quot;">​</a></h1><div class="epigraph"><p>压缩的 Picard 在函数空间上就是：猜一个 $v_0$，反复套贝尔曼算子，几何收敛到唯一值函数。</p><footer>—— 据 Stokey, Lucas and Prescott, Recursive Methods in Economic Dynamics, 1989, 第 4、9 章整理</footer></div><p>上一课<a href="/econ/bellman-equation">贝尔曼方程</a>把动态规划收成 \\(v=Tv\\)，并用<a href="/econ/contraction-mapping">压缩映射</a>保证唯一不动点。缺口是把存在变成可算：值函数迭代（VFI）即 \\(v_{n+1}=Tv_n\\)。本课只补算法、误差与它和策略迭代的分工，不把数值网格、插值写成计算附录，也不重推 Blackwell。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>任取 \\(v_0\\in C(S)\\)，令 \\(v_{n+1}=Tv_n\\)，即 \\(v_{n+1}(s)=\\max_{a\\in\\Gamma(s)}\\{F(s,a)+\\beta v_n(g(s,a))\\}\\)。 \\(\\|v_n-v\\|\\le \\beta^n\\|v_0-v\\|\\)，或用残差 \\(\\|v_{n+1}-v_n\\|/(1-\\beta)\\) 界住与真值的距离。有限期 \\(T\\) 步的向后归纳恰好是从 \\(v\\equiv 0\\)（或终端值）做 \\(T\\) 次 \\(T\\) 算子；无穷期是同一程序跑到残差小于容许。</p><p>策略 \\(\\Gamma_n(s)=\\arg\\max\\{F+\\beta v_n\\circ g\\}\\) 本身 UHC，极限策略的图闭包含于真最优对应。单值时策略也收敛。这是后课定量宏观「先解值函数再模拟路径」的数学许可。本课不进入校准。</p><h3 id="迭代的是值-不是状态" tabindex="-1">迭代的是值，不是状态 <a class="header-anchor" href="#迭代的是值-不是状态" aria-label="Permalink to &quot;迭代的是值，不是状态&quot;">​</a></h3><p>VFI 更新的是整张函数 \\(v\\)，不是沿一条资本路径做梯度下降。把 \\(k_{t+1}=f(k_t)\\) 反复迭代，那是状态的动态，收敛到稳态资本——另一回事，而且可能有鞍点要逆向。值函数迭代在函数空间里走压缩，与状态是否稳定无关。不要把「资本迭代」叫做 VFI。</p><p><span class="marginnote">\\(\\beta\\) 接近 \\(1\\) 时几何比很慢。加速：Howard 策略迭代（对固定策略解线性方程再改进策略）、修正策略迭代、代数多重网格。理论主干仍是：\\(T\\) 是压缩，VFI 收敛。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>离散状态、有限行动：每步对每个 \\(s\\) 扫一遍 \\(a\\)，复杂度 \\(|S|\\times|A|\\)。连续状态要离散化：网格太稀则近似的算子不再是原 \\(T\\) 的压缩扰动可控；误差分析把投影/插值当成对 \\(T\\) 的扰动，真压缩模 \\(\\beta\\) 仍给出对不动点的界——前提是近似算子也把函数空间送进自身。随机问题每步多一次对下期分布的积分，条件期望的数值是后课概率单元的计算面，概念上仍是套 \\(T\\)。</p><p>单调性：若 \\(v_0\\le Tv_0\\)，则序列上升且有上界 \\(v\\)，从下方逼近。猜一个可行策略的值当 \\(v_0\\)，常得到单调链。这比任意初值更稳，尤其在无界回报用加权范数时。</p>',12)),(t(),o(s,null,{default:n(()=>[l(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20V0%5B%22%E5%88%9D%E5%80%BC%20v0%22%5D%20--%3E%20T%5B%22%E5%A5%97%E8%B4%9D%E5%B0%94%E6%9B%BC%E7%AE%97%E5%AD%90%20T%22%5D%0A%20%20T%20--%3E%20V1%5B%22v1%2C%20v2%2C%20...%22%5D%0A%20%20V1%20--%3E%20CONV%5B%22%E5%87%A0%E4%BD%95%E6%94%B6%E6%95%9B%E5%88%B0%20v%22%5D%0A%20%20CONV%20--%3E%20PI%5B%22%E5%8F%96%E5%87%BA%20argmax%20%E7%AD%96%E7%95%A5%22%5D%0A%20%20PI%20--%3E%20PATH%5B%22%E7%94%A8%E7%AD%96%E7%95%A5%E7%94%9F%E6%88%90%E7%8A%B6%E6%80%81%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"每套一次 \\(T\\)，相当于把「再多看一期精确、更远用旧的 \\(v_n\\) 近似」的视界往前推。压缩说远期货币的误差被 \\(\\beta^n\\) 抽干，所以不必真的从无穷远处算起。这与有限 \\(n\\) 期模型再令 \\(n\\to\\infty\\) 是同一极限，只是实现上用函数迭代而不是每次重解一条变长的序列。",-1)),a[5]||(a[5]=e("p",null,"策略迭代往往有限步精确（离散有限问题）或二次收敛，因为它在策略空间交替「估值 / 改进」。VFI 更简单、每步只做最大化，理论接口最短：就是 Picard。主干先会 VFI；计算课再换 Howard。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"近似解的欧拉残差小，不自动等于值函数误差小，但压缩把值误差钉在残差上。报告时优先残差与 \\(\\|Tv-v\\|\\)，而不是「看起来稳态合理」。")],-1)),(t(),o(s,null,{default:n(()=>[l(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20V0%5B%22v0%EF%BC%9A%E8%A7%86%E7%95%8C%E4%B8%BA%200%20%E7%9A%84%E7%8C%9C%E6%B5%8B%22%5D%20--%3E%20T1%5B%22%E5%A5%97%E4%B8%80%E6%AC%A1%20T%EF%BC%9A1%20%E6%9C%9F%E7%B2%BE%E7%A1%AE%22%5D%0A%20%20T1%20--%3E%20V1%5B%22v1%20%E2%89%88%201%20%E6%9C%9F%E9%97%AE%E9%A2%98%E7%9A%84%E7%9C%9F%E5%80%BC%22%5D%0A%20%20V1%20--%3E%20T2%5B%22%E5%86%8D%E5%A5%97%E4%B8%80%E6%AC%A1%EF%BC%9A2%20%E6%9C%9F%E7%B2%BE%E7%A1%AE%22%5D%0A%20%20T2%20--%3E%20VN%5B%22vn%20%E2%89%88%20n%20%E6%9C%9F%E9%97%AE%E9%A2%98%E7%9A%84%E7%9C%9F%E5%80%BC%22%5D%0A%20%20VN%20--%3E%20INF%5B%22n%20%E8%B6%8B%E4%BA%8E%E6%97%A0%E7%A9%B7%EF%BC%9A%E9%80%BC%E8%BF%91%E6%97%A0%E7%A9%B7%E6%9C%9F%20v%22%5D%0A%20%20ERR%5B%22%E8%BF%9C%E6%9C%9F%E8%AF%AF%E5%B7%AE%E8%A2%AB%20%CE%B2%5En%20%E6%8A%BD%E5%B9%B2%22%5D%20--%3E%20INF%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">数字实例：收敛速度由 \\(\\beta\\) 决定。\\(\\beta=0.95\\) 时误差每步乘 0.95，要缩到千分之一需迭代约 \\(\\ln 0.001/\\ln 0.95 \\approx 135\\) 次；\\(\\beta=0.99\\) 时要约 688 次。这就是「\\(\\beta\\) 贴近 1 时几何比很慢」的具体账——也是 Howard 策略迭代存在的理由。</span></p><p><span class="marginnote">直觉类比：VFI 像练「多看一步棋」。\\(v_0\\) 是只会看 0 步的棋手；套一次贝尔曼算子，变成能看 1 步的棋手——当步收益精确、更远的局面用旧眼光打分。每套一次棋力涨一期，压缩映射保证最终棋路唯一，而且不用真下无穷多步。</span></p><p><span class="marginnote">常见误区：把「资本 \\(k_{t+1}=f(k_t)\\) 反复代入收敛到稳态」叫值函数迭代。那是状态在动；VFI 更新的是「每个状态下我能得多少分」这张整表 \\(v(k)\\)，与某一条资本路径是否稳定无关。两者都用「迭代」这个词，对象完全不同。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 GPU 实现、不比较投影法与扰动法（Judd）。连续时间黏性解的数值是另一套。也不把 VFI 用于没有折扣压缩的博弈完美均衡计算——那可能要不动点算法而不是 Picard。概率单元从下一课开始：随机贝尔曼里的期望，需要样本空间与条件期望，不再假设转移是确定的 \\(g\\)。</p><p>后课默认：折扣 DP 可用 VFI 逼近 \\(v\\)；误差由 \\(\\beta^n\\) 与 \\(\\|Tv_n-v_n\\|\\) 控制；取出的策略生成后课宏观路径。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VFI 是贝尔曼算子的 Picard，几何比 \\(\\beta\\)。</li><li>迭代对象是值函数，不是状态路径。</li><li>残差给出与真值的显式界；策略从 argmax 取出。</li><li>策略迭代更快，不是本课的定义。</li><li>下一课：<a href="/econ/sigma-algebra">样本空间与 σ-代数</a>。</li><li>出处：Stokey, Lucas and Prescott 第 4、9 章。</li></ul>',8))])}const b=A(B,[["render",v]]);export{F as __pageData,b as default};
